 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, SRGBColorSpace, DoubleSide } = ctx.THREE;

  const group = new Group();
  const timelines = [];
  const primitiveRefs = [];

  const atlasW = 512;
  const atlasH = 320;
  const aspect = atlasW / atlasH;
  const planeWidth = 1.6;
  const planeHeight = planeWidth / aspect;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({ transparent: true, side: DoubleSide });
  const sprite = new Mesh(geometry, material);
  group.add(sprite);

  const colors = config?.intent?.visualSpec?.colors ?? config?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const items = config?.textContent ?? config?.intent?.visualSpec?.textContent ?? [];
  const item = items.find((t) => t.role === 'headline') ?? items[0];
  if (item) {
    const textNode = ctx.fontAtlas.createText(String(item.text), {
      fontSize: item.typography?.fontSize ?? 39,
      color: colors.paper ?? '#e8ecf2',
      align: 'center',
      maxWidthPx: atlasW,
    });
    textNode.position.set(0, 0, 0.01);
    group.add(textNode);
  }

  let loadedTexture = null;
  const imageUrl = config?.imageUrl ?? config?.intent?.visualSpec?.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      loadedTexture = tex;
      tex.colorSpace = SRGBColorSpace;
      tex.needsUpdate = true;

      const tw = tex.image.width || atlasW;
      const th = tex.image.height || atlasH;
      const sx = atlasW / tw;
      const sy = atlasH / th;
      const offU = 0 / tw;
      const offV = 0 / th;

      material.map = texture(tex, uv().mul(vec2(sx, sy)).add(vec2(offU, offV)));
      material.needsUpdate = true;
    });
  }

  for (const p of config?.cinematicPrimitives ?? []) {
    if (ctx.primitives[p?.name]) {
      const ref = ctx.primitives[p.name](group, p.params ?? {});
      if (ref?.timeline) timelines.push(ref.timeline);
      if (ref?.cleanup) primitiveRefs.push(ref);
    }
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((t) => {
      if (t && typeof t.kill === 'function') t.kill();
    });
    primitiveRefs.forEach((r) => {
      if (r && typeof r.cleanup === 'function') r.cleanup();
    });
    if (loadedTexture) loadedTexture.dispose();
    geometry.dispose();
    material.dispose();
  };

  return group;
}
